{'content': '// Towel Hook - Wall mounted with M3 flat head screw
// Designed for 3D printing - sturdy construction for heavy towels

$fn = 64;

// Main parameters
wall_plate_width = 30;
wall_plate_height = 40;
wall_plate_thickness = 5;

// Screw hole parameters (M3 flat head)
screw_hole_diameter = 3.4;  // Clearance for M3 screw
screw_head_diameter = 6.5;  // M3 flat head countersink diameter
screw_head_depth = 2;       // Countersink depth

// Hook parameters
hook_thickness = 8;         // Thick for strength
hook_width = 20;            // Width of the hook arm
hook_length = 45;           // How far hook extends from wall
hook_curve_radius = 15;     // Inner radius of the hook curve
hook_tip_length = 20;       // Length of upward tip to prevent towel sliding off

// Reinforcement fillet
fillet_radius = 12;

module wall_plate() {
    difference() {
        // Rounded rectangle plate
        hull() {
            for (x = [-1, 1]) {
                for (y = [-1, 1]) {
                    translate([x * (wall_plate_width/2 - 5), y * (wall_plate_height/2 - 5), 0])
                        cylinder(r = 5, h = wall_plate_thickness);
                }
            }
        }

        // Countersunk screw hole - positioned in upper portion
        translate([0, wall_plate_height/4, -0.1]) {
            // Through hole
            cylinder(d = screw_hole_diameter, h = wall_plate_thickness + 0.2);
            // Countersink from back (flip direction for flat head)
            translate([0, 0, wall_plate_thickness + 0.1])
                mirror([0, 0, 1])
                    cylinder(d1 = screw_hole_diameter, d2 = screw_head_diameter, h = screw_head_depth);
        }
    }
}

module hook_arm() {
    // Main horizontal arm extending from plate
    translate([0, -wall_plate_height/2 + hook_width/2, wall_plate_thickness])
        rotate([0, 90, 0])
            linear_extrude(height = hook_length)
                translate([-hook_thickness/2, -hook_width/2])
                    square([hook_thickness, hook_width]);
}

module hook_curve() {
    // The curved part of the hook
    translate([hook_length, -wall_plate_height/2 + hook_width/2, wall_plate_thickness - hook_curve_radius - hook_thickness/2])
        rotate([90, 0, 0])
            rotate_extrude(angle = 180, convexity = 10)
                translate([hook_curve_radius + hook_thickness/2, 0])
                    circle(d = hook_thickness);

    // Create the curved section as a solid for better strength
    translate([hook_length, -wall_plate_height/2 + hook_width/2, wall_plate_thickness - hook_curve_radius - hook_thickness/2])
        rotate([90, 0, 0])
            linear_extrude(height = hook_width)
                difference() {
                    translate([0, 0])
                        circle(r = hook_curve_radius + hook_thickness);
                    translate([0, 0])
                        circle(r = hook_curve_radius);
                    translate([-hook_curve_radius - hook_thickness - 1, -hook_curve_radius - hook_thickness - 1])
                        square([2 * (hook_curve_radius + hook_thickness + 1), hook_curve_radius + hook_thickness + 1]);
                }
}

module hook_tip() {
    // Upward pointing tip to hold towel
    translate([hook_length - hook_curve_radius - hook_thickness/2, -wall_plate_height/2 + hook_width/2, 
               wall_plate_thickness - 2*hook_curve_radius - hook_thickness])
        rotate([90, 0, 0])
            linear_extrude(height = hook_width, center = true)
                hull() {
                    circle(d = hook_thickness);
                    translate([0, -hook_tip_length + hook_thickness/2])
                        circle(d = hook_thickness * 0.7);  // Slightly tapered tip
                }
}

module reinforcement_fillet() {
    // Triangular reinforcement between plate and arm
    translate([0, -wall_plate_height/2 + hook_width/2, wall_plate_thickness])
        rotate([90, 0, 0])
            linear_extrude(height = hook_width, center = true)
                polygon([
                    [0, 0],
                    [fillet_radius, 0],
                    [0, fillet_radius]
                ]);
}

module towel_hook() {
    union() {
        wall_plate();
        hook_arm();
        hook_curve();
        hook_tip();
        reinforcement_fillet();
    }
}

// Render the hook
towel_hook();
'}

{'content': '// Towel Hook - Wall mounted with M3 flat head screw
// Designed for 3D printing - sturdy construction for heavy towels

$fn = 64;

// Main parameters
wall_plate_width = 30;
wall_plate_height = 45;
wall_plate_thickness = 5;

// Screw hole parameters (M3 flat head)
screw_hole_diameter = 3.4;  // Clearance for M3 screw
screw_head_diameter = 6.5;  // M3 flat head countersink diameter
screw_head_depth = 2;       // Countersink depth

// Hook parameters
hook_thickness = 8;         // Thick for strength
hook_width = 22;            // Width of the hook arm
hook_length = 50;           // How far hook extends from wall
hook_curve_radius = 12;     // Inner radius of the hook curve
hook_tip_length = 25;       // Length of upward tip to prevent towel sliding off

// Reinforcement fillet
fillet_size = 15;

// Position of hook on plate (lower portion)
hook_y_offset = -8;

module wall_plate() {
    difference() {
        // Rounded rectangle plate
        hull() {
            for (x = [-1, 1]) {
                for (y = [-1, 1]) {
                    translate([x * (wall_plate_width/2 - 5), y * (wall_plate_height/2 - 5), 0])
                        cylinder(r = 5, h = wall_plate_thickness);
                }
            }
        }

        // Countersunk screw hole - positioned in upper portion
        translate([0, wall_plate_height/4 + 3, -0.1]) {
            // Through hole
            cylinder(d = screw_hole_diameter, h = wall_plate_thickness + 0.2);
            // Countersink from back for flat head screw
            translate([0, 0, -0.1])
                cylinder(d1 = screw_head_diameter, d2 = screw_hole_diameter, h = screw_head_depth + 0.1);
        }
    }
}

module hook_profile() {
    // 2D profile of the hook - will be extruded
    // Start from wall plate, go out, curve down and back, then up for tip

    outer_r = hook_curve_radius + hook_thickness;
    inner_r = hook_curve_radius;

    // Create the hook shape as a 2D profile
    union() {
        // Horizontal arm (from plate outward)
        translate([0, 0])
            square([hook_length, hook_thickness]);

        // Curved section (180 degree turn)
        translate([hook_length, -hook_curve_radius])
            difference() {
                circle(r = outer_r);
                circle(r = inner_r);
                // Remove top half
                translate([-outer_r - 1, 0])
                    square([2 * outer_r + 2, outer_r + 1]);
            }

        // Upward tip
        translate([hook_length - outer_r, -2 * hook_curve_radius - hook_thickness])
            square([hook_thickness, hook_tip_length + hook_thickness]);
    }
}

module reinforcement() {
    // Triangular gusset for strength
    linear_extrude(height = hook_width, center = true)
        polygon([
            [0, wall_plate_thickness],
            [fillet_size, wall_plate_thickness],
            [0, wall_plate_thickness + fillet_size]
        ]);
}

module towel_hook() {
    union() {
        // Wall mounting plate
        wall_plate();

        // Hook arm - extruded from 2D profile
        translate([0, hook_y_offset, wall_plate_thickness + hook_thickness/2])
            rotate([90, 0, 0])
                rotate([0, -90, 0])
                    translate([0, -hook_thickness, 0])
                        linear_extrude(height = hook_width, center = true)
                            hook_profile();

        // Reinforcement gusset
        translate([0, hook_y_offset, 0])
            reinforcement();
    }
}

// Render the hook
towel_hook();
'}

{'content': '// Towel Hook - Wall mounted with M3 flat head screw
// Designed for 3D printing - sturdy construction for heavy towels

$fn = 64;

// Main parameters
wall_plate_width = 32;
wall_plate_height = 50;
wall_plate_thickness = 5;

// Screw hole parameters (M3 flat head)
screw_hole_diameter = 3.4;  // Clearance for M3 screw
screw_head_diameter = 6.5;  // M3 flat head countersink diameter
screw_head_depth = 2.5;     // Countersink depth

// Hook parameters
hook_thickness = 10;        // Thick for strength
hook_width = 24;            // Width of the hook arm
hook_length = 45;           // How far hook extends from wall
hook_curve_radius = 14;     // Inner radius of the hook curve
hook_tip_length = 28;       // Length of upward tip to prevent towel sliding off

// Reinforcement gusset
gusset_length = 20;
gusset_height = 20;

// Position of hook on plate (lower portion)
hook_y_offset = -10;

module rounded_rect(w, h, r) {
    hull() {
        for (x = [-1, 1]) {
            for (y = [-1, 1]) {
                translate([x * (w/2 - r), y * (h/2 - r)])
                    circle(r = r);
            }
        }
    }
}

module wall_plate() {
    difference() {
        // Rounded rectangle plate
        linear_extrude(height = wall_plate_thickness)
            rounded_rect(wall_plate_width, wall_plate_height, 5);

        // Countersunk screw hole - positioned in upper portion
        translate([0, wall_plate_height/4, -0.1]) {
            // Through hole
            cylinder(d = screw_hole_diameter, h = wall_plate_thickness + 0.2);
            // Countersink from back for flat head screw (cone on mounting surface)
            translate([0, 0, -0.1])
                cylinder(d1 = screw_head_diameter, d2 = screw_hole_diameter, h = screw_head_depth + 0.1);
        }
    }
}

module hook_arm() {
    // Main arm extending from the wall
    hull() {
        // Base at wall plate
        translate([0, 0, 0])
            rotate([0, 90, 0])
                cylinder(d = hook_thickness, h = 0.1);
        // End before curve
        translate([hook_length - hook_curve_radius, 0, 0])
            rotate([0, 90, 0])
                cylinder(d = hook_thickness, h = 0.1);
    }
}

module hook_curve_section() {
    // 180 degree curve
    translate([hook_length - hook_curve_radius, 0, -hook_curve_radius - hook_thickness/2])
        rotate([90, 0, 0])
            rotate_extrude(angle = 180)
                translate([hook_curve_radius + hook_thickness/2, 0])
                    circle(d = hook_thickness);
}

module hook_tip() {
    // Upward pointing tip
    hull() {
        // Bottom of tip (after curve)
        translate([hook_length - 2*hook_curve_radius - hook_thickness, 0, -hook_curve_radius - hook_thickness/2])
            rotate([0, 90, 0])
                cylinder(d = hook_thickness, h = 0.1);
        // Top of tip (tapered slightly)
        translate([hook_length - 2*hook_curve_radius - hook_thickness, 0, -hook_curve_radius - hook_thickness/2 + hook_tip_length])
            sphere(d = hook_thickness * 0.8);
    }
}

module hook_complete() {
    // Complete hook extruded along width
    translate([0, hook_width/2, 0]) {
        hook_arm();
        hook_curve_section();
        hook_tip();
    }
    translate([0, -hook_width/2, 0]) {
        hook_arm();
        hook_curve_section();
        hook_tip();
    }

    // Fill between the two sides
    translate([0, 0, 0]) {
        // Arm fill
        translate([0, -hook_width/2, -hook_thickness/2])
            cube([hook_length - hook_curve_radius, hook_width, hook_thickness]);

        // Curve fill
        translate([hook_length - hook_curve_radius, -hook_width/2, -hook_curve_radius - hook_thickness])
            rotate([-90, 0, 0])
                linear_extrude(height = hook_width)
                    difference() {
                        circle(r = hook_curve_radius + hook_thickness);
                        circle(r = hook_curve_radius);
                        translate([0, -hook_curve_radius - hook_thickness - 1])
                            square([hook_curve_radius + hook_thickness + 2, 2*(hook_curve_radius + hook_thickness + 1)]);
                    }

        // Tip fill
        translate([hook_length - 2*hook_curve_radius - hook_thickness, -hook_width/2, -hook_curve_radius - hook_thickness])
            cube([hook_thickness, hook_width, hook_tip_length - hook_thickness/2]);

        // Rounded tip top
        translate([hook_length - 2*hook_curve_radius - hook_thickness/2, 0, -hook_curve_radius - hook_thickness/2 + hook_tip_length])
            scale([1, hook_width/hook_thickness, 1])
                sphere(d = hook_thickness * 0.8);
    }
}

module gusset() {
    // Reinforcement triangular gusset with rounded edge
    hull() {
        // Base at wall
        translate([0.1, 0, 0])
            rotate([0, 90, 0])
                cylinder(d = hook_thickness, h = 0.1);
        // Along arm
        translate([gusset_length, 0, 0])
            rotate([0, 90, 0])
                cylinder(d = hook_thickness, h = 0.1);
        // Up on wall
        translate([0.1, 0, gusset_height])
            rotate([0, 90, 0])
                cylinder(d = hook_thickness, h = 0.1);
    }
}

module reinforcement() {
    // Triangular gussets on both sides of hook
    translate([0, hook_width/2 - hook_thickness/2, 0])
        gusset();
    translate([0, -hook_width/2 + hook_thickness/2, 0])
        gusset();

    // Fill between gussets at wall
    translate([0, -hook_width/2 + hook_thickness/2, -hook_thickness/2])
        cube([hook_thickness/2, hook_width - hook_thickness, gusset_height + hook_thickness]);
}

module towel_hook() {
    union() {
        // Wall mounting plate
        wall_plate();

        // Hook arm positioned on lower part of plate
        translate([0, hook_y_offset, wall_plate_thickness + hook_thickness/2])
            hook_complete();

        // Reinforcement gussets
        translate([0, hook_y_offset, wall_plate_thickness + hook_thickness/2])
            reinforcement();
    }
}

// Render the hook
towel_hook();
'}

{'content': '// Towel Hook - Wall mounted with M3 flat head screw
// Designed for 3D printing - sturdy construction for heavy towels
// Print orientation: lay flat with wall plate on print bed

$fn = 64;

// Main parameters
wall_plate_width = 32;
wall_plate_height = 50;
wall_plate_thickness = 5;

// Screw hole parameters (M3 flat head)
screw_hole_diameter = 3.4;  // Clearance for M3 screw
screw_head_diameter = 6.5;  // M3 flat head countersink diameter
screw_head_depth = 2.5;     // Countersink depth

// Hook parameters
hook_thickness = 10;        // Thick for strength (good layer adhesion)
hook_width = 24;            // Width of the hook arm
hook_length = 45;           // How far hook extends from wall
hook_curve_radius = 14;     // Inner radius of the hook curve
hook_tip_length = 28;       // Length of upward tip to prevent towel sliding off

// Reinforcement gusset
gusset_length = 18;
gusset_height = 18;

// Position of hook on plate (lower portion)
hook_y_offset = -10;

module rounded_rect(w, h, r) {
    hull() {
        for (x = [-1, 1]) {
            for (y = [-1, 1]) {
                translate([x * (w/2 - r), y * (h/2 - r)])
                    circle(r = r);
            }
        }
    }
}

module wall_plate() {
    difference() {
        // Rounded rectangle plate
        linear_extrude(height = wall_plate_thickness)
            rounded_rect(wall_plate_width, wall_plate_height, 5);

        // Countersunk screw hole - positioned in upper portion
        translate([0, wall_plate_height/4, -0.1]) {
            // Through hole
            cylinder(d = screw_hole_diameter, h = wall_plate_thickness + 0.2);
            // Countersink from back for flat head screw (cone on mounting surface)
            translate([0, 0, -0.1])
                cylinder(d1 = screw_head_diameter, d2 = screw_hole_diameter, h = screw_head_depth + 0.1);
        }
    }
}

module hook_2d_profile() {
    // 2D profile that will be extruded
    outer_r = hook_curve_radius + hook_thickness;
    inner_r = hook_curve_radius;

    union() {
        // Horizontal arm
        translate([0, -hook_thickness/2])
            square([hook_length - hook_curve_radius + 0.1, hook_thickness]);

        // Curved section (180 degrees, going down)
        translate([hook_length - hook_curve_radius, -hook_curve_radius - hook_thickness/2])
            difference() {
                circle(r = outer_r);
                circle(r = inner_r);
                // Keep only left half (the curve going down and back)
                translate([0, -outer_r - 1])
                    square([outer_r + 1, 2 * outer_r + 2]);
            }

        // Upward tip
        translate([hook_length - 2*hook_curve_radius - hook_thickness, -2*hook_curve_radius - hook_thickness + 0.1])
            square([hook_thickness, hook_tip_length + 2*hook_curve_radius + hook_thickness - hook_thickness/2]);

        // Rounded tip top
        translate([hook_length - 2*hook_curve_radius - hook_thickness/2, hook_tip_length - hook_thickness/2])
            circle(d = hook_thickness);
    }
}

module hook_body() {
    // Extrude the 2D hook profile
    translate([0, -hook_width/2, 0])
        rotate([90, 0, 0])
            rotate([0, 0, -90])
                linear_extrude(height = hook_width)
                    hook_2d_profile();
}

module gusset_2d() {
    // 2D triangular gusset profile with rounded corners
    hull() {
        translate([hook_thickness/2, hook_thickness/2])
            circle(d = hook_thickness);
        translate([gusset_length - hook_thickness/2, hook_thickness/2])
            circle(d = hook_thickness);
        translate([hook_thickness/2, gusset_height - hook_thickness/2])
            circle(d = hook_thickness);
    }
}

module gussets() {
    // Two side gussets
    gusset_offset = hook_width/2 - hook_thickness/2;

    translate([0, gusset_offset, -hook_thickness/2])
        rotate([90, 0, 0])
            linear_extrude(height = hook_thickness)
                gusset_2d();

    translate([0, -gusset_offset + hook_thickness, -hook_thickness/2])
        rotate([90, 0, 0])
            linear_extrude(height = hook_thickness)
                gusset_2d();

    // Connecting bar between gussets at the base
    translate([0, -hook_width/2 + hook_thickness/2, -hook_thickness/2])
        cube([hook_thickness, hook_width - hook_thickness, gusset_height]);
}

module towel_hook() {
    union() {
        // Wall mounting plate
        wall_plate();

        // Hook body positioned on lower part of plate
        translate([0, hook_y_offset, wall_plate_thickness + hook_thickness/2])
            hook_body();

        // Reinforcement gussets
        translate([0, hook_y_offset, wall_plate_thickness + hook_thickness/2])
            gussets();
    }
}

// Render the hook
towel_hook();
